// Bundled web fonts. Sans = DM Sans (UI text, same as web baseline).
// Serif = "SavorSerif" alias for Lora — the rounded bookish serif of the
// concept mockups (the web CSS says "Instrument Serif" but the mockup
// letterforms are clearly rounder/sturdier; Lora is the accepted match).
// LATIN subsets (verified: a-z A-Z 0-9 present). WOFF keeps the original
// outlines while wx.loadFontFace owns both WebView and native rendering.
const FACES = [
  { family: 'DMSans', weight: '400', source: 'url("data:font/woff;base64,")' },
  { family: 'DMSans', weight: '500', source: 'url("data:font/woff;base64,")' },
  { family: 'DMSans', weight: '700', source: 'url("data:font/woff;base64,")' },
  { family: 'SavorSerif', weight: '400', source: 'url("data:font/woff;base64,")' },
  { family: 'SavorSerif', weight: '500', source: 'url("data:font/woff;base64,")' }
];

let started = false;
function initFonts() {
  if (started) return;
  started = true;
  FACES.forEach(function (face) {
    wx.loadFontFace({
      global: true,
      family: face.family,
      source: face.source,
      desc: { weight: face.weight },
      scopes: ['webview', 'native'],
      success: function () {
        console.log('[savor] font ready:', face.family, face.weight);
      },
      fail: function (error) {
        console.warn('[savor] font FAILED:', face.family, face.weight, error && error.errMsg);
      },
    });
  });
}

module.exports = { initFonts };
